    case 'Cubic':
      return Cubic(fuseReq(decDouble(m['a']), 'Cubic.Cubic', 'a'), fuseReq(decDouble(m['b']), 'Cubic.Cubic', 'b'), fuseReq(decDouble(m['c']), 'Cubic.Cubic', 'c'), fuseReq(decDouble(m['d']), 'Cubic.Cubic', 'd'));
    case 'ThreePointCubic':
      return ThreePointCubic(fuseReq(decOffset(m['a1']), 'ThreePointCubic.ThreePointCubic', 'a1'), fuseReq(decOffset(m['b1']), 'ThreePointCubic.ThreePointCubic', 'b1'), fuseReq(decOffset(m['midpoint']), 'ThreePointCubic.ThreePointCubic', 'midpoint'), fuseReq(decOffset(m['a2']), 'ThreePointCubic.ThreePointCubic', 'a2'), fuseReq(decOffset(m['b2']), 'ThreePointCubic.ThreePointCubic', 'b2'));
    case 'CatmullRomCurve':
      return CatmullRomCurve(fuseReq(fuseList<Offset>(m['controlPoints'], (e) => decOffset(e)!), 'CatmullRomCurve.CatmullRomCurve', 'controlPoints'), tension: decDouble(m['tension']) ?? 0.0);
    case 'CatmullRomCurve.precompute':
      return CatmullRomCurve.precompute(fuseReq(fuseList<Offset>(m['controlPoints'], (e) => decOffset(e)!), 'CatmullRomCurve.precompute', 'controlPoints'), tension: decDouble(m['tension']) ?? 0.0);
    case 'FlippedCurve':
      return FlippedCurve(fuseReq(decCurve(m['curve']), 'FlippedCurve.FlippedCurve', 'curve'));
    case 'ElasticInCurve':
      return ElasticInCurve(decDouble(m['period']) ?? 0.4);
    case 'ElasticOutCurve':
      return ElasticOutCurve(decDouble(m['period']) ?? 0.4);
    case 'ElasticInOutCurve':
      return ElasticInOutCurve(decDouble(m['period']) ?? 0.4);
  }
  return fuseBad('Curve', v);
}

Duration? decDuration(Object? v) {
  if (v == null) return null;
  final nDuration = niceDuration(v);
  if (nDuration != null) return nDuration;
  if (v is String) {
    return switch (v) {
      'Durations.short1' => Durations.short1,
      'Durations.short2' => Durations.short2,
      'Durations.short3' => Durations.short3,
      'Durations.short4' => Durations.short4,
      'Durations.medium1' => Durations.medium1,
      'Durations.medium2' => Durations.medium2,
      'Durations.medium3' => Durations.medium3,
      'Durations.medium4' => Durations.medium4,
      'Durations.long1' => Durations.long1,
      'Durations.long2' => Durations.long2,
      'Durations.long3' => Durations.long3,
      'Durations.long4' => Durations.long4,
      'Durations.extralong1' => Durations.extralong1,
      'Durations.extralong2' => Durations.extralong2,
      'Durations.extralong3' => Durations.extralong3,
      'Durations.extralong4' => Durations.extralong4,
      'zero' => Duration.zero,
      _ => fuseBad('Duration', v),
    };
  }
  final m = v as Map;
  switch (m[r'$']) {
    case null:
      return Duration(days: decInt(m['days']) ?? 0, hours: decInt(m['hours']) ?? 0, minutes: decInt(m['minutes']) ?? 0, seconds: decInt(m['seconds']) ?? 0, milliseconds: decInt(m['milliseconds']) ?? 0, microseconds: decInt(m['microseconds']) ?? 0);
  }
  return fuseBad('Duration', v);
}

Locale? decLocale(Object? v) {
  if (v == null) return null;
  final m = v as Map;
  switch (m[r'$']) {
    case null:
      return Locale(fuseReq(decString(m['_languageCode']), 'Locale', '_languageCode'), decString(m['_countryCode']));
    case 'fromSubtags':
      return Locale.fromSubtags(languageCode: decString(m['languageCode']) ?? 'und', scriptCode: decString(m['scriptCode']), countryCode: decString(m['countryCode']));
  }
  return fuseBad('Locale', v);
}

LocalizationsDelegate<pull_to_refresh.RefreshLocalizations>? decLocalizationsDelegateOfRefreshLocalizations(Object? v) {
  if (v == null) return null;
  final m = v as Map;
  switch (m[r'$']) {
    case 'RefreshLocalizationsDelegate':
      return pull_to_refresh.RefreshLocalizationsDelegate();
  }
  return fuseBad('LocalizationsDelegate<pull_to_refresh.RefreshLocalizations>', v);
}

Offset? decOffset(Object? v) {
  if (v == null) return null;
  if (v is String) {
    return switch (v) {
      'zero' => Offset.zero,
      'infinite' => Offset.infinite,
      _ => fuseBad('Offset', v),
    };
  }
  final m = v as Map;
  switch (m[r'$']) {
    case null:
      return Offset(fuseReq(decDouble(m['dx']), 'Offset', 'dx'), fuseReq(decDouble(m['dy']), 'Offset', 'dy'));
    case 'fromDirection':
      return Offset.fromDirection(fuseReq(decDouble(m['direction']), 'Offset.fromDirection', 'direction'), decDouble(m['distance']) ?? 1.0);
  }
  return fuseBad('Offset', v);
}

